mod.request(
      {
        protocol: url.protocol,
        hostname: url.hostname,
        port: url.port || (isHttps ? 443 : 80),
        path: `${url.pathname}${url.search}`,
        method: 'GET',
        headers: { ...init.headers, Host: url.host },
        servername: isHttps ? url.hostname.replace(/^\[|\]$/g, '') : undefined,
        // 🔑 DNS 를 다시 풀지 않는다. 검사한 그 주소로만 간다.
        lookup: ((_h: string, opts: { all?: boolean }, cb: (...a: unknown[]) => void) => {
          if (opts && opts.all) cb(null, [{ address: init.address, family: init.family }]);
          else cb(null, init.address, init.family);
        }) as unknown as http.RequestOptions['lookup'],
      },
      (res) => {
        const headers = new Headers();
        for (const [k, v] of Object.entries(res.headers)) {
          if (v === undefined) continue;
          if (Array.isArray(v)) v.forEach((x) => headers.append(k, x));
          else headers.set(k, v);
        }
        const status = res.statusCode ?? 0;
        if (status < 200 || status > 599) {
          res.resume();
          reject(new Error(`HTTP 상태를 해석할 수 없습니다: ${status}`));
          return;
        }
        resolve(new Response(Readable.toWeb(res) as unknown as ReadableStream, { status, statusText: res.statusMessage ?? '', headers }));
      },
    )

